//! Retry configuration.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RetryConfig {
    /// Total attempts allowed, including the first call. Must be >= 1.
    pub max_attempts: u32,
    /// Base delay before the first retry, in milliseconds.
    pub base_delay_ms: u64,
    /// Maximum delay between retries, in milliseconds.
    pub max_delay_ms: u64,
}

impl RetryConfig {
    /// Returns the delay for a retry after `retry_index` previous retries.
    pub(crate) fn delay_for_retry(&self, retry_index: u32) -> u64 {
        let mut delay = self.base_delay_ms.min(self.max_delay_ms);

        // Multiply only while it can still affect the capped result. This
        // avoids constructing an overflowing exponent for large attempts.
        for _ in 0..retry_index {
            delay = delay.saturating_mul(2).min(self.max_delay_ms);
            if delay == self.max_delay_ms {
                break;
            }
        }

        delay
    }
}

#[cfg(test)]
mod tests {
    use super::RetryConfig;

    #[test]
    fn delay_saturates_without_overflowing() {
        let config = RetryConfig {
            max_attempts: u32::MAX,
            base_delay_ms: u64::MAX,
            max_delay_ms: u64::MAX,
        };

        assert_eq!(config.delay_for_retry(u32::MAX), u64::MAX);
    }

    #[test]
    fn delay_is_capped_at_each_step() {
        let config = RetryConfig {
            max_attempts: 5,
            base_delay_ms: 3,
            max_delay_ms: 10,
        };

        assert_eq!(config.delay_for_retry(0), 3);
        assert_eq!(config.delay_for_retry(1), 6);
        assert_eq!(config.delay_for_retry(2), 10);
        assert_eq!(config.delay_for_retry(100), 10);
    }
}

